import React from 'react';
import {
  Chart as ChartJS, CategoryScale, LinearScale, BarElement, LineElement,
  PointElement, ArcElement, Tooltip, Legend, Filler
} from 'chart.js';
import { Bar, Doughnut, Line } from 'react-chartjs-2';
import './Analytics.css';

ChartJS.register(CategoryScale, LinearScale, BarElement, LineElement,
  PointElement, ArcElement, Tooltip, Legend, Filler);

const CATEGORY_COLORS = [
  '#c9a84c','#2dd4bf','#f472b6','#60a5fa','#fb923c','#a78bfa','#4ade80','#f87171','#94a3b8',
];

const CHART_DEFAULTS = {
  plugins: {
    legend: { labels: { color: '#9baab8', font: { family: 'DM Sans', size: 12 }, boxWidth: 12, padding: 16 } },
    tooltip: {
      backgroundColor: '#12181f', borderColor: 'rgba(255,255,255,0.1)', borderWidth: 1,
      titleColor: '#f0f4f8', bodyColor: '#9baab8', padding: 12,
      callbacks: { label: ctx => ` $${Number(ctx.raw).toLocaleString('en-US', { minimumFractionDigits: 2 })}` }
    }
  },
  scales: {
    x: { grid: { color: 'rgba(255,255,255,0.04)' }, ticks: { color: '#576475', font: { family: 'DM Sans' } } },
    y: {
      grid: { color: 'rgba(255,255,255,0.04)' },
      ticks: {
        color: '#576475', font: { family: 'DM Sans' },
        callback: v => '$' + v.toLocaleString()
      }
    }
  }
};

export default function Analytics({ monthlyTrend, categoryBreakdown, totalIncome, totalExpenses, netSavings }) {
  const labels = monthlyTrend.map(m => m.month);

  // Bar chart: income vs expenses
  const barData = {
    labels,
    datasets: [
      {
        label: 'Income',
        data: monthlyTrend.map(m => m.income),
        backgroundColor: 'rgba(74,222,128,0.7)',
        borderRadius: 6, borderSkipped: false,
      },
      {
        label: 'Expenses',
        data: monthlyTrend.map(m => m.expenses),
        backgroundColor: 'rgba(248,113,113,0.7)',
        borderRadius: 6, borderSkipped: false,
      },
    ],
  };

  // Line chart: savings trend
  const lineData = {
    labels,
    datasets: [
      {
        label: 'Savings',
        data: monthlyTrend.map(m => m.savings),
        borderColor: '#c9a84c',
        backgroundColor: 'rgba(201,168,76,0.08)',
        tension: 0.4, fill: true, pointRadius: 5,
        pointBackgroundColor: '#c9a84c',
        pointBorderColor: '#0d1117', pointBorderWidth: 2,
      },
    ],
  };

  // Doughnut: category breakdown
  const catEntries = Object.entries(categoryBreakdown).sort((a, b) => b[1] - a[1]);
  const doughnutData = {
    labels: catEntries.map(([k]) => k),
    datasets: [{
      data: catEntries.map(([, v]) => v),
      backgroundColor: CATEGORY_COLORS.slice(0, catEntries.length),
      borderWidth: 0,
      hoverOffset: 8,
    }],
  };

  const fmt = v => `$${v.toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 0 })}`;

  const highestMonth = monthlyTrend.reduce((best, m) => m.savings > best.savings ? m : best, monthlyTrend[0] || {});
  const avgExpenses = monthlyTrend.reduce((s, m) => s + m.expenses, 0) / (monthlyTrend.length || 1);

  return (
    <div className="analytics-page">
      <div className="page-header">
        <div>
          <h1 className="page-title">Analytics</h1>
          <p className="page-subtitle">6-month spending trends & insights</p>
        </div>
      </div>

      {/* Insight chips */}
      <div className="insight-row">
        <div className="insight-chip">
          <span className="insight-icon">📈</span>
          <span className="insight-label">Best Savings Month</span>
          <span className="insight-val gold">{highestMonth.month} — {fmt(highestMonth.savings || 0)}</span>
        </div>
        <div className="insight-chip">
          <span className="insight-icon">📊</span>
          <span className="insight-label">Avg Monthly Expenses</span>
          <span className="insight-val red">{fmt(avgExpenses)}</span>
        </div>
        <div className="insight-chip">
          <span className="insight-icon">💰</span>
          <span className="insight-label">This Month Net</span>
          <span className={`insight-val ${netSavings >= 0 ? 'green' : 'red'}`}>{fmt(netSavings)}</span>
        </div>
      </div>

      {/* Charts row 1 */}
      <div className="charts-row-2">
        <div className="chart-card wide">
          <div className="chart-title">Income vs Expenses — 6 Months</div>
          <Bar data={barData} options={{ ...CHART_DEFAULTS, responsive: true, maintainAspectRatio: false }} height={260} />
        </div>

        <div className="chart-card">
          <div className="chart-title">Spending by Category</div>
          {catEntries.length === 0 ? (
            <div className="empty-state">No expense data</div>
          ) : (
            <Doughnut data={doughnutData} options={{
              responsive: true, maintainAspectRatio: false,
              plugins: {
                legend: { position: 'bottom', labels: { color: '#9baab8', font: { family: 'DM Sans', size: 11 }, padding: 10, boxWidth: 10 } },
                tooltip: { backgroundColor: '#12181f', borderColor: 'rgba(255,255,255,0.1)', borderWidth: 1, titleColor: '#f0f4f8', bodyColor: '#9baab8', padding: 12,
                  callbacks: { label: ctx => ` ${ctx.label}: $${Number(ctx.raw).toFixed(0)}` }
                }
              },
              cutout: '65%',
            }} height={260} />
          )}
        </div>
      </div>

      {/* Charts row 2 */}
      <div className="chart-card">
        <div className="chart-title">Savings Trend — 6 Months</div>
        <Line data={lineData} options={{
          ...CHART_DEFAULTS, responsive: true, maintainAspectRatio: false,
          plugins: { ...CHART_DEFAULTS.plugins, legend: { display: false } },
          scales: {
            ...CHART_DEFAULTS.scales,
            y: {
              ...CHART_DEFAULTS.scales.y,
              ticks: {
                ...CHART_DEFAULTS.scales.y.ticks,
                callback: v => (v >= 0 ? '+' : '') + '$' + v.toLocaleString()
              }
            }
          }
        }} height={200} />
      </div>

      {/* Monthly breakdown table */}
      <div className="chart-card">
        <div className="chart-title">Monthly Summary</div>
        <div className="summary-table">
          <div className="summary-header">
            <span>Month</span><span>Income</span><span>Expenses</span>
            <span>Savings</span><span>Rate</span>
          </div>
          {monthlyTrend.slice().reverse().map(m => {
            const rate = m.income > 0 ? (m.savings / m.income * 100) : 0;
            return (
              <div key={m.month} className="summary-row">
                <span className="sum-month">{m.month}</span>
                <span className="sum-income">{fmt(m.income)}</span>
                <span className="sum-expense">{fmt(m.expenses)}</span>
                <span className={`sum-savings ${m.savings >= 0 ? 'pos' : 'neg'}`}>{fmt(m.savings)}</span>
                <span className={`sum-rate ${rate >= 20 ? 'good' : rate < 0 ? 'bad' : ''}`}>{rate.toFixed(1)}%</span>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}
